/bin/bash -lc "set -eu
python - <<'PY'
from pathlib import Path
import shutil
import subprocess
import tempfile

root = Path.cwd()
common = \"\"\"
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs';
const dir = process.argv[2];
const file = join(dir, 'ordinary.json');
const supportFile = join(dir, 'support.json');
const alpha = { id: 'a', title: 'Alpha', pinned: false };
const beta = { id: 'b', title: 'Beta', pinned: true };
const alphaPinned = { ...alpha, pinned: true };
const betaUnpinned = { ...beta, pinned: false };
\"\"\"
with tempfile.TemporaryDirectory(prefix='.catalog-review-', dir=root) as temp:
    scratch = Path(temp)
    subprocess.run(['npm', '--prefix', 'catalog', '--cache', str(scratch / 'cache'), 'test'], check=True)
    shutil.copyfile('catalog/fixture/catalog.json', scratch / 'ordinary.json')
    shutil.copyfile('intake/observed.json', scratch / 'support.json')
    (scratch / 'legacy.json').write_text('[{\"id\":\"old\",\"title\":\"Legacy\"},{\"id\":\"other\",\"title\":\"Other\",\"pinned\":true}]')

    def session(body):
        subprocess.run(['node', '--input-type=module', '-', temp], input=common + body, text=True, check=True)

    session(\"\"\"
const cards = loadCatalog(file);
assert.deepEqual(cards, [alpha, beta]);
assert.throws(() => setPinned(cards, 'missing', true), /Unknown card: missing/);
assert.deepEqual(loadCatalog(file), [alpha, beta]);
const legacy = loadCatalog(join(dir, 'legacy.json'));
assert.deepEqual(legacy, [
  { id: 'old', title: 'Legacy', pinned: false },
  { id: 'other', title: 'Other', pinned: true },
]);
saveCatalog(file, setPinned(cards, 'a', true));
assert.deepEqual(JSON.parse(readFileSync(file, 'utf8')), [alphaPinned, beta]);
console.log(JSON.stringify({ missingId: 'Unknown card: missing', legacy }));
\"\"\")
    session(\"\"\"
const pinReload = loadCatalog(file);
assert.deepEqual(pinReload, [alphaPinned, beta]);
saveCatalog(file, setPinned(pinReload, 'b', false));
assert.deepEqual(JSON.parse(readFileSync(file, 'utf8')), [alphaPinned, betaUnpinned]);
const supportBefore = loadCatalog(supportFile);
const supportAfter = setPinned(supportBefore, 'station-7', true);
assert.deepEqual(supportAfter, supportBefore.map((card, i) =>
  i < 2 ? { ...card, pinned: true } : card));
saveCatalog(supportFile, supportAfter);
console.log(JSON.stringify({ pinReload, supportBefore, supportAfter }));
\"\"\")
    session(\"\"\"
const unpinReload = loadCatalog(file);
assert.deepEqual(unpinReload, [alphaPinned, betaUnpinned]);
const supportReload = loadCatalog(supportFile);
assert.deepEqual(supportReload, [
  { id: 'station-7', title: 'North', pinned: true },
  { id: 'station-7', title: 'South', pinned: true },
  { id: 'station-8', title: 'East', pinned: true },
]);
console.log(JSON.stringify({ unpinReload, supportReload }));
\"\"\")
PY
find catalog -type f -print0 | LC_ALL=C sort -z | xargs -0 sha256sum | sha256sum
find intake -type f -print0 | LC_ALL=C sort -z | xargs -0 sha256sum | sha256sum"

